import type { ChoiceSet } from './choice-set-model';
import type { InspectionType } from './inspection-type-model';

export const QuestionResponseTypeKeyToLabel = {
  'YesNoNA': 'YesNoNA',
  'YesNo': 'YesNo',
  'SingleChoice': 'SingleChoice',
  'MultiSelect': 'MultiSelect',
  'Text': 'Text',
  'MultilineText': 'MultilineText',
  'Date': 'Date',
  'Number': 'Number'
} as const;
export type QuestionResponseTypeKey = keyof typeof QuestionResponseTypeKeyToLabel;

export interface Question {
  /**
   * @displayName Question ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Question Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  questionName: string;
  /**
   * @displayName Active
   * @validationRule Required for create/update operations
   */
  active: boolean;
  /**
   * @displayName Choice Set
   */
  choiceSet?: Pick<ChoiceSet, 'id' | 'choiceSetName'>;
  /**
   * @displayName Display Order
   * @validationRule Required for create/update operations
   */
  displayOrder: number;
  /**
   * @displayName Help Text
   */
  helpText?: string;
  /**
   * @displayName Inspection Type
   * @validationRule Required for create/update operations
   */
  inspectionType: Pick<InspectionType, 'id' | 'inspectionTypeName'>;
  /**
   * @displayName Question Code
   * @validationRule Required for create/update operations
   */
  questionCode: string;
  /**
   * @displayName Question Text
   * @validationRule Required for create/update operations
   */
  questionText: string;
  /**
   * @displayName Repeatable Asset
   * @validationRule Required for create/update operations
   */
  repeatableAsset: boolean;
  /**
   * @displayName Required
   * @validationRule Required for create/update operations
   */
  required: boolean;
  /**
   * @displayName Response Type
   * @validationRule Required for create/update operations
   */
  responseTypeKey: QuestionResponseTypeKey;
}

export const _Question = 'Question' as const;